    public String greet() {
        return "Hola";
    }
}

class Person {
    private Greeter g;

    Person(Greeter g) {
        this.g = g;
    }

    void setGreeter(Greeter g) {
        this.g = g;
    }

    String say() {
        return g.greet();
    }
}

public class Example {
    public static void main(String[] args) {
        Person p = new Person(new English());
        System.out.print(p.say());
        p.setGreeter(new Spanish());
        System.out.print(p.say());
    }
}

